def kmeans(X,K,it=50,seed=0):
    rng=np.random.default_rng(seed); C=X[rng.choice(len(X),K,replace=False)]
    for _ in range(it):
        a=np.argmax(X@C.T,1)
        for k in range(K):
            m=X[a==k]
            if len(m): c=m.sum(0); C[k]=c/np.linalg.norm(c)
    return C,a,(X*C[a]).sum(1).mean()
